content:
:root {
  font-family: 'Inter', system-ui, Avenir, Helvetica, Arial, sans-serif;
  line-height: 1.5;
  font-weight: 400;

  color-scheme: dark;
  --color-text: rgba(255, 255, 255, 0.87);
  --color-bg: #05050f;
  --color-panel-bg: rgba(15, 15, 30, 0.85);
  --color-border: rgba(255, 255, 255, 0.1);
  --color-primary: #4f46e5;
  --color-primary-hover: #4338ca;
  --color-card-bg: rgba(25, 25, 45, 0.6);
  --color-card-hover: rgba(35, 35, 65, 0.8);

  color: var(--color-text);
  background-color: var(--color-bg);

  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  width: 100%;
  min-height: 100vh;
  min-height: 100dvh;
  overflow: hidden;
  background: radial-gradient(circle at center, #1b1b3a 0%, var(--color-bg) 100%);
}

.app-container {
  position: relative;
  width: 100%;
  min-height: 100vh;
  min-height: 100dvh;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.header {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  padding: 1rem 2rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: linear-gradient(to bottom, rgba(5, 5, 15, 0.9), transparent);
  z-index: 10;
  pointer-events: none;
}

.header h1 {
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  color: #fff;
  text-shadow: 0 0 10px rgba(255, 255, 255, 0.5);
}

.canvas-container {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 1;
}

.control-panel {
  position: absolute;
  top: 80px;
  right: 20px;
  width: 350px;
  max-height: calc(100vh - 100px);
  background: var(--color-panel-bg);
  backdrop-filter: blur(10px);
  border: 1px solid var(--color-border);
  border-radius: 12px;
  padding: 1.5rem;
  z-index: 10;
  overflow-y: auto;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
  display: flex;
  flex-direction: column;
  gap: 1.2rem;
  pointer-events: auto;
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 255, 255, 0.2) rgba(0, 0, 0, 0.1);
}

.control-panel::-webkit-scrollbar {
  width: 6px;
}

.control-panel::-webkit-scrollbar-track {
  background: rgba(0, 0, 0, 0.1);
  border-radius: 3px;
}

.control-panel::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.2);
  border-radius: 3px;
}

.planet-card {
  background: var(--color-card-bg);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 8px;
  padding: 1rem;
  transition: all 0.3s ease;
  cursor: pointer;
}

.planet-card:hover {
  background: var(--color-card-hover);
  border-color: rgba(255, 255, 255, 0.2);
  transform: translateY(-2px);
}

.planet-card.active {
  border-color: var(--color-primary);
  box-shadow: 0 0 15px rgba(79, 70, 229, 0.4);
}

.btn {
  background: var(--color-primary);
  color: white;
  border: none;
  border-radius: 6px;
  padding: 0.6rem 1.2rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  box-shadow: 0 4px 12px rgba(79, 70, 229, 0.3);
}

.btn:hover {
  background: var(--color-primary-hover);
}

.btn:active {
  transform: scale(0.98);
}

.info-text {
  font-size: 0.875rem;
  color: rgba(255, 255, 255, 0.7);
  line-height: 1.6;
}

@media (max-width: 768px) {
  .control-panel {
    top: auto;
    bottom: 0;
    right: 0;
    left: 0;
    width: 100%;
    max-height: 50vh;
    border-bottom-left-radius: 0;
    border-bottom-right-radius: 0;
    border-top-left-radius: 16px;
    border-top-right-radius: 16px;
    padding: 1rem;
  }

  .header {
    padding: 1rem;
  }

  .header h1 {
    font-size: 1.2rem;
  }
}

/**
 * 惑星データのインターフェース
 */
export interface PlanetData {
  /** 一意の識別子 */
  id?: string;
  /** 惑星名 */
  name: string;
  /** 惑星の半径 */
  radius: number;
  /** 太陽からの距離 */
  distance: number;
  /** 公転速度 */
  speed: number;
  /** 惑星の色 */
  color: string;
  /** 惑星の説明文 */
  description: string;
  /** テクスチャ画像のパス（オプション） */
  textureUrl?: string;
}

import { useEffect, useRef } from 'react'
import * as THREE from 'three'
import { PlanetData } from '../types'
import '../index.css'

interface SolarSystemProps {
  planets: PlanetData[];
  speedMultiplier: number;
  selectedPlanet: PlanetData | null;
  onSelectPlanet: (planet: PlanetData | null) => void;
  isPaused: boolean;
}

export default function SolarSystem({
  planets,
  speedMultiplier,
  selectedPlanet,
  onSelectPlanet,
  isPaused
}: SolarSystemProps) {
  const containerRef = useRef<HTMLDivElement>(null)
  const sceneRef = useRef<THREE.Scene | null>(null)
  const cameraRef = useRef<THREE.PerspectiveCamera | null>(null)
  const rendererRef = useRef<THREE.WebGLRenderer | null>(null)
  const planetMeshesRef = useRef<{ [key: string]: THREE.Mesh }>({})
  const anglesRef = useRef<{ [key: string]: number }>({})

  // 最新の props を ref で保持し、アニメーションループやイベント内で参照する
  const planetsRef = useRef(planets)
  planetsRef.current = planets
  const speedMultiplierRef = useRef(speedMultiplier)
  speedMultiplierRef.current = speedMultiplier
  const isPausedRef = useRef(isPaused)
  isPausedRef.current = isPaused
  const selectedPlanetRef = useRef(selectedPlanet)
  selectedPlanetRef.current = selectedPlanet

  useEffect(() => {
    if (!containerRef.current) return

    // シーンの初期化
    const scene = new THREE.Scene()
    sceneRef.current = scene

    // カメラの初期化
    const camera = new THREE.PerspectiveCamera(
      60,
      containerRef.current.clientWidth / containerRef.current.clientHeight,
      0.1,
      1000
    )
    camera.position.set(0, 50, 100)
    camera.lookAt(0, 0, 0)
    cameraRef.current = camera

    // レンダラーの初期化
    const renderer = new THREE.WebGLRenderer({ antialias: true })
    renderer.setSize(containerRef.current.clientWidth, containerRef.current.clientHeight)
    renderer.setPixelRatio(window.devicePixelRatio)
    containerRef.current.appendChild(renderer.domElement)
    rendererRef.current = renderer

    // ライティング
    const ambientLight = new THREE.AmbientLight(0x333333)
    scene.add(ambientLight)

    const pointLight = new THREE.PointLight(0xffffff, 2, 300)
    pointLight.position.set(0, 0, 0)
    scene.add(pointLight)

    // 星空背景
    const starsGeometry = new THREE.BufferGeometry()
    const starsCount = 2000
    const starPositions = new Float32Array(starsCount * 3)
    for (let i = 0; i < starsCount * 3; i++) {
      starPositions[i] = (Math.random() - 0.5) * 500
    }
    starsGeometry.setAttribute('position', new THREE.BufferAttribute(starPositions, 3))
    const starsMaterial = new THREE.PointsMaterial({ color: 0xffffff, size: 0.7 })
    const starField = new THREE.Points(starsGeometry, starsMaterial)
    scene.add(starField)

    // 太陽の作成
    const sunGeometry = new THREE.SphereGeometry(5, 32, 32)
    const sunMaterial = new THREE.MeshBasicMaterial({ color: 0xffaa00 })
    const sunMesh = new THREE.Mesh(sunGeometry, sunMaterial)
    scene.add(sunMesh)

    // リソース解放用のリスト
    const geometriesToDispose: THREE.BufferGeometry[] = [starsGeometry, sunGeometry]
    const materialsToDispose: THREE.Material[] = [starsMaterial, sunMaterial]

    // 惑星と軌道の作成
    planetsRef.current.forEach((planet) => {
      if (anglesRef.current[planet.name] === undefined) {
        anglesRef.current[planet.name] = Math.random() * Math.PI * 2
      }

      // 軌道ライン
      const orbitGeometry = new THREE.BufferGeometry()
      const points = []
      for (let i = 0; i <= 64; i++) {
        const theta = (i / 64) * Math.PI * 2
        points.push(
          new THREE.Vector3(
            Math.cos(theta) * planet.distance,
            0,
            Math.sin(theta) * planet.distance
          )
        )
      }
      orbitGeometry.setFromPoints(points)
      geometriesToDispose.push(orbitGeometry)

      const orbitMaterial = new THREE.LineBasicMaterial({
        color: 0xffffff,
        transparent: true,
        opacity: 0.15
      })
      materialsToDispose.push(orbitMaterial)

      const orbitLine = new THREE.Line(orbitGeometry, orbitMaterial)
      scene.add(orbitLine)

      // 惑星メッシュ
      const planetGeometry = new THREE.SphereGeometry(planet.radius, 32, 32)
      geometriesToDispose.push(planetGeometry)

      const planetMaterial = new THREE.MeshStandardMaterial({
        color: planet.color,
        roughness: 0.8
      })
      materialsToDispose.push(planetMaterial)

      const planetMesh = new THREE.Mesh(planetGeometry, planetMaterial)
      planetMesh.userData = { planetData: planet }
      scene.add(planetMesh)
      planetMeshesRef.current[planet.name] = planetMesh
    })

    // レイキャスト用（クリック検出）
    const raycaster = new THREE.Raycaster()
    const mouse = new THREE.Vector2()

    const handlePointerDown = (event: MouseEvent) => {
      if (!containerRef.current || !cameraRef.current || !sceneRef.current) return
      const rect = containerRef.current.getBoundingClientRect()
      mouse.x = ((event.clientX - rect.left) / rect.width) * 2 - 1
      mouse.y = -((event.clientY - rect.top) / rect.height) * 2 + 1

      raycaster.setFromCamera(mouse, cameraRef.current)
      const intersects = raycaster.intersectObjects(sceneRef.current.children)

      for (const intersect of intersects) {
        if (intersect.object.userData && intersect.object.userData.planetData) {
          onSelectPlanet(intersect.object.userData.planetData)
          return
        }
      }
    }

    const currentContainer = containerRef.current
    currentContainer.addEventListener('pointerdown', handlePointerDown)

    // ウィンドウリサイズ対応
    const handleResize = () => {
      if (!containerRef.current || !rendererRef.current || !cameraRef.current) return
      const width = containerRef.current.clientWidth
      const height = containerRef.current.clientHeight
      cameraRef.current.aspect = width / height
      cameraRef.current.updateProjectionMatrix()
      rendererRef.current.setSize(width, height)
    }
    window.addEventListener('resize', handleResize)

    // アニメーションループ（Clockによるデルタタイム適用）
    const clock = new THREE.Clock()
    let animationFrameId: number

    const animate = () => {
      animationFrameId = requestAnimationFrame(animate)
      const delta = clock.getDelta()

      if (!isPausedRef.current) {
        planetsRef.current.forEach((planet) => {
          const mesh = planetMeshesRef.current[planet.name]
          if (mesh) {
            anglesRef.current[planet.name] += planet.speed * speedMultiplierRef.current * delta * 0.5
            const angle = anglesRef.current[planet.name]
            mesh.position.x = Math.cos(angle) * planet.distance
            mesh.position.z = Math.sin(angle) * planet.distance
            mesh.rotation.y += delta * 0.5
          }
        })
      }

      // 選択された惑星にカメラを追従（デルタタイムを用いたスムーズなlerp）
      if (selectedPlanetRef.current && cameraRef.current) {
        const mesh = planetMeshesRef.current[selectedPlanetRef.current.name]
        if (mesh) {
          const targetPos = mesh.position.clone()
          const desiredCamPos = new THREE.Vector3(targetPos.x, targetPos.y + 10, targetPos.z + 15)
          cameraRef.current.position.lerp(desiredCamPos, Math.min(delta * 3.0, 1.0))
          cameraRef.current.lookAt(targetPos)
        }
      }

      if (rendererRef.current && sceneRef.current && cameraRef.current) {
        rendererRef.current.render(sceneRef.current, cameraRef.current)
      }
    }

    animate()

    return () => {
      cancelAnimationFrame(animationFrameId)
      window.removeEventListener('resize', handleResize)
      if (currentContainer) {
        currentContainer.removeEventListener('pointerdown', handlePointerDown)
        if (rendererRef.current && rendererRef.current.domElement) {
          if (currentContainer.contains(rendererRef.current.domElement)) {
            currentContainer.removeChild(rendererRef.current.domElement)
          }
        }
      }

      // メモリリーク防止のためのdispose処理
      geometriesToDispose.forEach((geom) => geom.dispose())
      materialsToDispose.forEach((mat) => mat.dispose())
      if (rendererRef.current) {
        rendererRef.current.dispose()
      }
    }
  }, []) // 依存配列を空にしてマウント時のみ初期化

  // 選択された惑星が解除された場合のカメラ位置リセット
  useEffect(() => {
    if (!selectedPlanet && cameraRef.current) {
      cameraRef.current.position.set(0, 50, 100)
      cameraRef.current.lookAt(0, 0, 0)
    }
  }, [selectedPlanet])

  return <div className="canvas-container" ref={containerRef} />
}

import { PlanetData } from '../types'
import '../index.css'

interface ControlPanelProps {
  planets: PlanetData[];
  selectedPlanet: PlanetData | null;
  onSelectPlanet: (planet: PlanetData | null) => void;
  speedMultiplier: number;
  onSpeedChange: (speed: number) => void;
  isPaused: boolean;
  onTogglePause: () => void;
}

export default function ControlPanel({
  planets,
  selectedPlanet,
  onSelectPlanet,
  speedMultiplier,
  onSpeedChange,
  isPaused,
  onTogglePause
}: ControlPanelProps) {
  return (
    <div className="control-panel" role="region" aria-label="太陽系コントロールパネル">
      <h2>太陽系コントロール</h2>

      <div style={{ display: 'flex', gap: '0.5rem', alignItems: 'center' }}>
        <button
          className="btn"
          onClick={onTogglePause}
          aria-label={isPaused ? 'シミュレーションを再生' : 'シミュレーションを一時停止'}
        >
          {isPaused ? '再生' : '一時停止'}
        </button>
        <button
          className="btn"
          onClick={() => onSelectPlanet(null)}
          style={{ background: '#334155' }}
          aria-label="全体視点に戻る"
        >
          全体視点に戻る
        </button>
      </div>

      <div className="info-text">
        公転速度: {speedMultiplier.toFixed(1)}x
      </div>
      <input
        type="range"
        min="0.1"
        max="5"
        step="0.1"
        value={speedMultiplier}
        onChange={(e) => onSpeedChange(parseFloat(e.target.value))}
        style={{ width: '100%', cursor: 'pointer' }}
        aria-label="公転速度調整スライダー"
      />

      <h3>惑星一覧</h3>
      <div style={{ display: 'flex', flexDirection: 'column', gap: '0.8rem' }} role="list" aria-label="惑星リスト">
        {planets.map((planet) => {
          const isSelected = selectedPlanet?.name === planet.name
          return (
            <div
              key={planet.name}
              className={`planet-card ${isSelected ? 'active' : ''}`}
              onClick={() => onSelectPlanet(planet)}
              role="button"
              tabIndex={0}
              onKeyDown={(e) => {
                if (e.key === 'Enter' || e.key === ' ') {
                  onSelectPlanet(planet)
                }
              }}
              aria-label={`${planet.name}を選択`}
            >
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '0.4rem' }}>
                <strong style={{ fontSize: '1.05rem', color: planet.color }}>{planet.name}</strong>
                <span className="info-text" style={{ fontSize: '0.75rem' }}>距離: {planet.distance}AU</span>
              </div>
              <p className="info-text">{planet.description}</p>
            </div>
          )
        })}
      </div>
    </div>
  )
}

import { useState, useEffect } from 'react'
import SolarSystem from './components/SolarSystem'
import ControlPanel from './components/ControlPanel'
import { PlanetData } from './types'
import { PLANETS_DATA } from './constants/planets'
import './index.css'

export default function App() {
  const [selectedPlanet, setSelectedPlanet] = useState<PlanetData | null>(null)
  const [speedMultiplier, setSpeedMultiplier] = useState<number>(1.0)
  const [isPaused, setIsPaused] = useState<boolean>(false)
  const [isLoading, setIsLoading] = useState<boolean>(true)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    document.title = '太陽系 3D シミュレーション'

    const timer = setTimeout(() => {
      try {
        if (!PLANETS_DATA || PLANETS_DATA.length === 0) {
          throw new Error('惑星データの読み込みに失敗しました。')
        }
        setIsLoading(false)
      } catch (err) {
        setError(err instanceof Error ? err.message : '予期せぬエラーが発生しました。')
        setIsLoading(false)
      }
    }, 300)

    return () => clearTimeout(timer)
  }, [])

  if (isLoading) {
    return (
      <div className="app-container" style={{ justifyContent: 'center', alignItems: 'center' }}>
        <div className="info-text">シミュレーションをロード中...</div>
      </div>
    )
  }

  if (error) {
    return (
      <div className="app-container" style={{ justifyContent: 'center', alignItems: 'center' }}>
        <div className="info-text" style={{ color: '#ef4444' }}>エラー: {error}</div>
      </div>
    )
  }

  return (
    <div className="app-container">
      <header className="header">
        <h1>太陽系 3D シミュレーション</h1>
      </header>

      <SolarSystem
        planets={PLANETS_DATA}
        speedMultiplier={speedMultiplier}
        selectedPlanet={selectedPlanet}
        onSelectPlanet={setSelectedPlanet}
        isPaused={isPaused}
      />

      <ControlPanel
        planets={PLANETS_DATA}
        selectedPlanet={selectedPlanet}
        onSelectPlanet={setSelectedPlanet}
        speedMultiplier={speedMultiplier}
        onSpeedChange={setSpeedMultiplier}
        isPaused={isPaused}
        onTogglePause={() => setIsPaused(!isPaused)}
      />
    </div>
  )
}
